+//
+
+import CoreGraphics
+
+/// Accumulate emitted paths in bounded groups, preserving append and subpath order.
+/// Count each append, including multiple paths emitted for a single off cell.
+internal struct QRCodeBatchedModulePath {
+	private let result = CGMutablePath()
+	private var batch = CGMutablePath()
+	private var count = 0
+
+	mutating func addPath(_ path: CGPath, transform: CGAffineTransform) {
+		batch.addPath(path, transform: transform)
+		count += 1
+		if count == 64 { flush() }
+	}
+
+	/// Return one vector path. Callers retain their existing final closeSubpath behavior.
+	mutating func finish() -> CGMutablePath {
+		if result.isEmpty { return batch }
+		if count > 0 { flush() }
+		return result
+	}
+
+	private mutating func flush() {
+		result.addPath(batch)
+		batch = CGMutablePath()
+		count = 0
+	}
+}
